from enum import Enum

class InputType(Enum):
    GENERAL = 1
    USERNAME = 2
    POSTAL_CODE = 3

validation_rules = {
    InputType.GENERAL: lambda x: not any(char.isdigit() for char in x),
    InputType.USERNAME: lambda x: True,  # Allow digits in usernames
    InputType.POSTAL_CODE: lambda x: any(char.isdigit() for char in x),  # Require digits in postal codes
}

def process_input(user_input, input_type):
    if not user_input:
        return "Error: Input cannot be empty"
    if not isinstance(user_input, str):
        return "Error: Input must be a string"

    # Check for null bytes
    try:
        user_input.encode('utf-8')
    except UnicodeEncodeError:
        return "Error: Input contains invalid characters"

    sanitized_input = user_input.strip().lower()
    if len(sanitized_input) > 255:
