class InputValidator:
    def __init__(self, input_type):
        self.input_type = input_type

    def validate(self, user_input):
        if not user_input:
            return "Error: Input cannot be empty"
        if not isinstance(user_input, str):
            return "Error: Input must be a string"

        # Check for null bytes
        try:
            user_input.encode('utf-8')
        except UnicodeEncodeError:
            return "Error: Input contains invalid characters"

        sanitized_input = user_input.strip().lower()
        if len(sanitized_input) > 255:
            return "Error: Input is too long"

        if self.input_type == 'username' and any(char.isdigit() for char in sanitized_input):
            pass  # Allow digits in usernames
        elif any(char.isdigit() for char in sanitized_input):
            return "Error: Input cannot contain numbers"

        return sanitized_input

class UsernameValidator(InputValidator):
    def __init__(self):
        super().__init__('username')

    def validate(self, user_input):
        # Add additional validation rules for usernames
        error = super().validate(user_input)
        if error:
            return error
        # Check for username length
        if len(user_input) < 3 or len(user_input) > 32:
            return "Error: Username must be between 3 and 32 characters"
        return user_input
```
